var CalendarObjectCard=(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),euro=n=>n==null||n===''?'Preis auf Anfrage':new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n));
function date(s){const v=String(s||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))?v:''}
function read(k){try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}}
function markup(item,statusMarkup=''){const x=item.snapshot||{},state=item.savedState||{},address=state.address||x,zip=address.zipcode!=null?String(address.zipcode).padStart(5,'0'):'',place=[zip,address.city].filter(Boolean).join(' ')||'Keine Angabe',rental=x.action==='mieten',price=rental?x.rent_price:x.price,sqm=(rental?x.rent_per_square_meter:x.price_per_square_meter)??(price!=null&&Number(x.square_meter)>0?Number(price)/Number(x.square_meter):null),year=Object.hasOwn(state,'year_override')?state.year_override:[x,...(x.portalListings||[])].map(v=>v.year_of_construction||v.year_built||v.yearBuilt||v.baujahr).find(Boolean),yearMatch=String(year||'').match(/\b(1\d{3}|20\d{2}|2100)\b/),listingDate=date(x.uptime_date||x.created_at),today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),days=listingDate?Math.round((Date.parse(today)-Date.parse(listingDate))/86400000):null,own=!!(x.created_at&&!x.uptime_date),note=state.note||{},edit='/suche.html#meine-objekte',keys=new Set([item.key,x.local_key||JSON.stringify([String(x.source||''),String(x.immo_id||'')]),...(x.portalListings||[]).map(v=>v.local_key||JSON.stringify([String(v.source||''),String(v.immo_id||'')]))]);
const cells=[['Wohnfläche',x.square_meter!=null?esc(x.square_meter)+' m²':'Keine Angabe'],['Preis pro m²'+(rental?' / Monat':''),euro(sqm)],[rental?'Kaltmiete / Monat':'Kaufpreis',euro(price)],['Ort',esc(place)],['Energieklasse',esc(String(x.energy_efficency_class||'').trim()||'Keine Angabe')],['Baujahr',yearMatch?yearMatch[1]:'Keine Angabe'],[own?'Angelegt am':'Erfasst seit',listingDate?listingDate.split('-').reverse().join('.')+(days>=0?`<span class="listing-age ${days<=60?'age-green':days<180?'age-orange':'age-red'}">${days} ${days===1?'Tag':'Tage'}${own?' gespeichert':''}</span>`:''):'Keine Angabe']];
const calculations=read('immobrain-fix-flip-saved-v1'),visits=read('immobrain-viewings-v1'),linked=(Array.isArray(calculations)?calculations:[]).filter(v=>keys.has(v.values?.listingRef)),viewings=[];let market='';if(typeof ImmoMarket!=='undefined'){ImmoMarket.refresh();market=ImmoMarket.markup(x,state,item.key).replace(/<button class="market-object-edit"[\s\S]*?<\/button>/,`<a class="market-object-edit" href="${edit}">Bearbeiten</a>`)}
const contact=item.contact||state.contact?.name||'',phone=item.phone||state.contact?.phone||'',phoneTarget=String(phone).replace(/[^+0-9*#]/g,'');return `<div class="calendar-object${state.dismissed?' is-dismissed':''}"><div class="calendar-card-top"><span class="badge">${rental?'Mieten':'Kaufen'} · ${esc(x.source||'Quelle nicht angegeben')}</span><a class="calendar-card-edit" href="${edit}">Objekt bearbeiten ↗</a></div>${state.custom?`<a class="own-object-tag" href="${edit}">Manuell angelegt</a>`:''}${[x,...(x.portalListings||[])].some(v=>v.renovation_needed===true)?'<span class="renovation-badge">Renovierungsbedürftig</span>':''}<h3>${esc(x.title||item.name||'Immobilienangebot')}</h3><div class="calendar-address-line"><div class="calendar-place">${esc(place)} · ${esc(address.street||'Straße nicht verfügbar')}</div>${statusMarkup}</div>${contact||phone?`<div class="calendar-contact">${contact?`<span>Ansprechpartner: <strong>${esc(contact)}</strong></span>`:''}${phone?`<a href="tel:${esc(phoneTarget)}" aria-label="${esc(contact||'Ansprechpartner')} anrufen">☎ ${esc(phone)}</a>`:''}</div>`:''}${state.dismissed?'<p>Aussortiert</p>':''}<dl class="card-details">${cells.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${market}${note.text||note.offer!=null||note.target!=null?`<section class="note-summary"><h4>Deine Notiz</h4>${note.text?`<p>${esc(note.text)}</p>`:''}<div class="note-prices">${note.offer!=null&&note.offer!==''?`<p>Kaufpreisangebot <strong>${euro(note.offer)}</strong></p>`:''}${note.target!=null&&note.target!==''?`<p>Ziel-Einkaufspreis <strong>${euro(note.target)}</strong></p>`:''}</div></section>`:''}${linked.length||viewings.length?`<div class="calendar-documents">${linked.length?`<section><strong>${linked.length} Kalkulation${linked.length===1?'':'en'}</strong>${linked.map(v=>`<a href="/fix-flip.html?calculation=${encodeURIComponent(v.id)}">${esc(v.name||'Kalkulation')} öffnen →</a>`).join('')}</section>`:''}${viewings.length?`<section><strong>${viewings.length} Besichtigung${viewings.length===1?'':'en'}</strong>${viewings.map(v=>`<a href="/besichtigung.html?viewing=${encodeURIComponent(v.id)}">${esc(v.data?.fields?.date||v.name||'Besichtigung')} öffnen →</a>`).join('')}</section>`:''}</div>`:''}</div>`}
return {markup};})();
